void run_network (input_t input_1[(128*128*1)], result_t layer7_out[1]) {
#pragma HLS DATAFLOW

 k_t layer4_out[(128*128*1)];
#pragma HLS ARRAY_PARTITION variable=layer4_out cyclic factor=64
 nnet::dense<input_t, k_t, kconfig4>(input_1, layer4_out, w7, b7);

    layer5_t layer5_out[4*4*64];
#pragma HLS ARRAY_PARTITION variable=layer5_out cyclic factor=64
 nnet::relu<k_t, layer5_t, krelu_config5>(layer4_out, layer5_out);

    layer6_t layer6_out[64];
#pragma HLS ARRAY_PARTITION variable=layer6_out cyclic factor=64
 nnet::global_pooling2d_cl<layer5_t, layer6_t, kconfig6>(layer5_out, layer6_out);

    nnet::dense<layer6_t, result_t, kconfig7>(layer6_out, layer7_out, w7, b7);
}

