void write_output (result_t layer7_out[1], hls::stream<axis512> &axis_out, uint64 dest) {
    uint512 out_raw = 0;
    union {
        float f;
        uint32_t u;
    };
    f = layer7_out[0];
    out_raw(31, 0) = u;
    axis512 word;
    word.data = out_raw;
    word.last = 0;
    word.dest = dest;
    word.keep = -1;
    word.strb = -1;
    axis_out.write(word);
}

void process_image (hls::stream<axis512> &axis_in, hls::stream<axis512> &axis_out, uint64 dest)
{
#pragma HLS DATAFLOW

 input_t input_1[128*128*1];
#pragma HLS ARRAY_PARTITION variable=input_1 cyclic factor=64
 result_t layer7_out[1];

    fill_input(input_1, axis_in);
    run_network(input_1, layer7_out);
    write_output(layer7_out, axis_out, dest);
}

